@pytest.mark.parametrize("name", [row[0] for row in _B1_CASES]) def test_s5a02_r2_b1_six_cases_classifier(name: str) -> None: """B1 六案(公共单条分类器):四不支持单位案降 unknown 族(机读 reason=requirement_unit_not_representable,保留原 unit/value/key); 合法 C 与空单位正控保持 compatible。""" _name, key, value, unit, fact_makers, expected, unit_kind = \ _b1_case(name) requirement = req(key, value, unit=unit) facts = [make() for make in fact_makers] result = _detailed(requirement, facts) assert result["classification"] == expected, name if expected == "condition_unknown": # 评审 B1 契约:不能丢 unit 后授 compatible/conflict;unknown # 由单位分支产生(reason 区分,不是缺事实/无来源) assert result["frozen_status"] is None, name assert "requirement_unit_not_representable" in result["reason"], \ name assert "no_applicable_fact" not in result["reason"], name assert "necessity_unsourced" not in result["reason"], name disclosure = result["mapping_disclosures"][0] assert disclosure["kind"] == unit_kind, name assert disclosure["key"] == key, name assert disclosure["unit"] == unit, name assert disclosure["value"] == repr(value), name assert disclosure["reason"] == unit_kind, name if unit_kind == "requirement_unit_noncanonical": assert "K" in disclosure["allowed_units"] or \ "C" in disclosure["allowed_units"], name else: # 合法正控:分类不降档;C 案无披露,空单位案披露 canonical-by-key unit_kinds = [d["kind"] for d in result["mapping_disclosures"] if str(d.get("kind", "")).startswith( "requirement_unit")] assert unit_kinds == ([unit_kind] if unit_kind else []), name if unit_kind == "requirement_unit_not_declared": disclosure = next(d for d in result["mapping_disclosures"] if d["kind"] == unit_kind) > assert disclosure["reason"] == \ ^^^^^^^^^^^^^^^^^^^^ "requirement_unit_canonical_by_key", name E KeyError: 'reason'
